-- BOOK_MY_SEAT: extend the existing demo show schedule by 15 additional days.
-- Run this AFTER database/seed.sql in MySQL Workbench, against book_my_seat.
-- Safe for existing bookings: this script never updates/deletes existing shows or bookings.
-- It copies the five-day seeded timetable (screen, local start time and category prices)
-- cyclically into the 15 dates immediately following the latest date already in shows.
-- New show IDs are generated by AUTO_INCREMENT; application code must treat show IDs as opaque IDs.

USE book_my_seat;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @old_sql_safe_updates = @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_bms_template_dates;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_template_shows;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_extension_dates;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_extension_plan;

-- Identify the five seeded timetable dates (normally 54 shows on each date).
CREATE TEMPORARY TABLE tmp_bms_template_dates (
  template_day TINYINT UNSIGNED NOT NULL PRIMARY KEY,
  template_date DATE NOT NULL UNIQUE
) ENGINE=InnoDB;

INSERT INTO tmp_bms_template_dates (template_day, template_date)
SELECT ROW_NUMBER() OVER (ORDER BY d.show_date) AS template_day, d.show_date
FROM (
  SELECT DATE(s.start_time + INTERVAL 330 MINUTE) AS show_date
  FROM shows s
  GROUP BY DATE(s.start_time + INTERVAL 330 MINUTE)
  HAVING COUNT(*) >= 30
  ORDER BY show_date DESC
  LIMIT 5
) AS d
ORDER BY d.show_date;

-- Keep the source show and its existing prices so the extension matches the seeded timetable.
CREATE TEMPORARY TABLE tmp_bms_template_shows (
  template_day TINYINT UNSIGNED NOT NULL,
  movie_id BIGINT UNSIGNED NOT NULL,
  screen_id BIGINT UNSIGNED NOT NULL,
  local_time TIME NOT NULL,
  duration_min SMALLINT UNSIGNED NOT NULL,
  standard_price DECIMAL(8,2) NOT NULL,
  premium_price DECIMAL(8,2) NOT NULL,
  recliner_price DECIMAL(8,2) NOT NULL,
  PRIMARY KEY (template_day, screen_id, local_time, movie_id)
) ENGINE=InnoDB;

INSERT INTO tmp_bms_template_shows
  (template_day, movie_id, screen_id, local_time, duration_min, standard_price, premium_price, recliner_price)
SELECT td.template_day, s.movie_id, s.screen_id,
       TIME(s.start_time + INTERVAL 330 MINUTE), m.duration_min,
       MAX(CASE WHEN sp.category = 'STANDARD' THEN sp.price END),
       MAX(CASE WHEN sp.category = 'PREMIUM' THEN sp.price END),
       MAX(CASE WHEN sp.category = 'RECLINER' THEN sp.price END)
FROM tmp_bms_template_dates td
JOIN shows s ON DATE(s.start_time + INTERVAL 330 MINUTE) = td.template_date
JOIN movies m ON m.id = s.movie_id
JOIN show_prices sp ON sp.show_id = s.id
GROUP BY td.template_day, s.movie_id, s.screen_id, s.start_time, m.duration_min
HAVING COUNT(DISTINCT sp.category) = 3;

-- Build the next 15 India-local dates after the latest date already present.
CREATE TEMPORARY TABLE tmp_bms_extension_dates (
  day_number TINYINT UNSIGNED NOT NULL PRIMARY KEY,
  show_date DATE NOT NULL UNIQUE
) ENGINE=InnoDB;

INSERT INTO tmp_bms_extension_dates (day_number, show_date)
WITH RECURSIVE day_numbers AS (
  SELECT 1 AS day_number
  UNION ALL
  SELECT day_number + 1 FROM day_numbers WHERE day_number < 15
)
SELECT n.day_number,
       DATE_ADD((SELECT MAX(DATE(start_time + INTERVAL 330 MINUTE)) FROM shows), INTERVAL n.day_number DAY)
FROM day_numbers n;

CREATE TEMPORARY TABLE tmp_bms_extension_plan (
  show_date DATE NOT NULL,
  movie_id BIGINT UNSIGNED NOT NULL,
  screen_id BIGINT UNSIGNED NOT NULL,
  start_utc DATETIME NOT NULL,
  duration_min SMALLINT UNSIGNED NOT NULL,
  standard_price DECIMAL(8,2) NOT NULL,
  premium_price DECIMAL(8,2) NOT NULL,
  recliner_price DECIMAL(8,2) NOT NULL,
  PRIMARY KEY (screen_id, start_utc),
  KEY idx_tmp_extension_movie (movie_id)
) ENGINE=InnoDB;

-- Repeat the five-day pattern in order for the 15 additional dates.
INSERT INTO tmp_bms_extension_plan
  (show_date, movie_id, screen_id, start_utc, duration_min, standard_price, premium_price, recliner_price)
SELECT ed.show_date, ts.movie_id, ts.screen_id,
       DATE_SUB(TIMESTAMP(ed.show_date, ts.local_time), INTERVAL 330 MINUTE),
       ts.duration_min, ts.standard_price, ts.premium_price, ts.recliner_price
FROM tmp_bms_extension_dates ed
JOIN tmp_bms_template_shows ts
  ON ts.template_day = MOD(ed.day_number - 1, 5) + 1;

-- Do not schedule over an existing show or create overlapping use of the same screen.
DELETE p
FROM tmp_bms_extension_plan p
WHERE EXISTS (
  SELECT 1
  FROM shows existing
  JOIN movies existing_movie ON existing_movie.id = existing.movie_id
  WHERE existing.screen_id = p.screen_id
    AND existing.start_time < p.start_utc + INTERVAL (p.duration_min + 15) MINUTE
    AND p.start_utc < existing.start_time + INTERVAL (existing_movie.duration_min + 15) MINUTE
);

-- Insert only missing shows. Existing booked shows are untouched.
INSERT INTO shows (movie_id, screen_id, start_time, status)
SELECT p.movie_id, p.screen_id, p.start_utc,
       IF(p.start_utc <= UTC_TIMESTAMP(), 'COMPLETED', 'SCHEDULED')
FROM tmp_bms_extension_plan p
WHERE NOT EXISTS (
  SELECT 1 FROM shows s
  WHERE s.screen_id = p.screen_id AND s.start_time = p.start_utc
);

-- Add the same three category prices to the newly created shows.
-- Use one scan of the temporary plan: MySQL cannot reopen a TEMPORARY table
-- multiple times in a UNION-derived table (ERROR 1137).
INSERT INTO show_prices (show_id, category, price)
SELECT s.id, price_rows.category,
       CASE price_rows.price_slot
         WHEN 1 THEN p.standard_price
         WHEN 2 THEN p.premium_price
         WHEN 3 THEN p.recliner_price
       END
FROM tmp_bms_extension_plan p
JOIN shows s
  ON s.screen_id = p.screen_id
 AND s.start_time = p.start_utc
CROSS JOIN (
  SELECT 'STANDARD' AS category, 1 AS price_slot
  UNION ALL SELECT 'PREMIUM', 2
  UNION ALL SELECT 'RECLINER', 3
) AS price_rows
WHERE NOT EXISTS (
  SELECT 1
  FROM show_prices existing_price
  WHERE existing_price.show_id = s.id
    AND existing_price.category = price_rows.category
)
AND (
  (price_rows.price_slot = 1 AND p.standard_price IS NOT NULL)
  OR (price_rows.price_slot = 2 AND p.premium_price IS NOT NULL)
  OR (price_rows.price_slot = 3 AND p.recliner_price IS NOT NULL)
);
COMMIT;

DROP TEMPORARY TABLE IF EXISTS tmp_bms_template_dates;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_template_shows;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_extension_dates;
DROP TEMPORARY TABLE IF EXISTS tmp_bms_extension_plan;
SET SQL_SAFE_UPDATES = @old_sql_safe_updates;

-- Verification: this should show the 15 added dates, all movies, and upcoming show counts.
SELECT DATE(s.start_time + INTERVAL 330 MINUTE) AS show_date_india,
       COUNT(*) AS total_shows,
       COUNT(DISTINCT s.movie_id) AS movies_with_shows
FROM shows s
WHERE DATE(s.start_time + INTERVAL 330 MINUTE) >
      DATE_SUB((SELECT MAX(DATE(start_time + INTERVAL 330 MINUTE)) FROM shows), INTERVAL 15 DAY)
GROUP BY DATE(s.start_time + INTERVAL 330 MINUTE)
ORDER BY show_date_india;

SELECT m.id, m.title, COUNT(s.id) AS future_shows
FROM movies m
LEFT JOIN shows s ON s.movie_id = m.id
  AND s.status = 'SCHEDULED'
  AND s.start_time > UTC_TIMESTAMP()
GROUP BY m.id, m.title
ORDER BY m.id;
